import sys, subprocess, difflib

path = sys.argv[1]
base_rev = sys.argv[2]
upstream_rev = sys.argv[3]

def show(rev):
    p = subprocess.run(["git", "show", f"{rev}:{path}"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if p.returncode != 0:
        sys.stderr.write(p.stderr.decode(errors="replace"))
        raise SystemExit(p.returncode)
    return p.stdout

base = show(base_rev).splitlines(keepends=True)
local = show("HEAD").splitlines(keepends=True)
upstream = show(upstream_rev).splitlines(keepends=True)

local_ins = {}
local_deleted = set()
sm_local = difflib.SequenceMatcher(None, base, local, autojunk=False)
for tag, i1, i2, j1, j2 in sm_local.get_opcodes():
    if tag == "insert":
        local_ins.setdefault(i1, []).extend(local[j1:j2])
    elif tag == "delete":
        for k in range(i1, i2):
            local_deleted.add(k)

out = []
emitted = set()

def emit_ins_at(p):
    if p not in emitted:
        for line in local_ins.get(p, []):
            out.append(line)
        emitted.add(p)

sm_up = difflib.SequenceMatcher(None, base, upstream, autojunk=False)
base_cursor = 0
for tag, i1, i2, j1, j2 in sm_up.get_opcodes():
    for p in range(base_cursor, i1):
        emit_ins_at(p)
    if tag == "equal":
        for k in range(i1, i2):
            emit_ins_at(k)
            if k not in local_deleted:
                out.append(upstream[j1 + (k - i1)])
        base_cursor = i2
    elif tag == "delete":
        for k in range(i1, i2):
            emit_ins_at(k)
        base_cursor = i2
    elif tag == "insert":
        emit_ins_at(i1)
        out.extend(upstream[j1:j2])
        base_cursor = i2
    elif tag == "replace":
        for k in range(i1, i2):
            emit_ins_at(k)
        out.extend(upstream[j1:j2])
        base_cursor = i2

for p in range(base_cursor, len(base) + 1):
    emit_ins_at(p)

with open(path, "wb") as f:
    f.write(b"".join(out))
PY
